// পুরনো একই id-র নোট সরিয়ে নতুন অধ্যায় বসানো; পুরনো প্রশ্নগুলো নতুন অধ্যায়ে যোগ হয়
(() => {
  const sscSubjects = new Set(SSC_CHAPTERS.map((chapter) => chapter.subjectId));
  const removedOld = STUDY_CHAPTERS.filter((note) => note.classId === "c9" && sscSubjects.has(note.subjectId));
  for (const chapter of SSC_CHAPTERS) {
    const old = STUDY_CHAPTERS.find((note) => note.id === chapter.id);
    if (old) {
      const seen = new Set(chapter.mcq.map((item) => item.q));
      chapter.mcq = [...chapter.mcq, ...old.mcq.filter((item) => !seen.has(item.q))];
      const seenShort = new Set(chapter.short.map((item) => item.q));
      chapter.short = [...chapter.short, ...old.short.filter((item) => !seenShort.has(item.q))];
      if (!chapter.example && old.example) chapter.example = old.example;
    }
  }
  // সঠিক উত্তর যেন একই অবস্থানে জমে না থাকে: প্রশ্নের লেখা থেকে নির্দিষ্ট ঘূর্ণন (প্রতিবার একই ফল)
  const fixedLast = /সবগুলো|সব কটি|কোনোটিতেই|কোনোটিই|দুটোতেই|সবার সমান|উভয়/;
  for (const chapter of SSC_CHAPTERS) {
    for (const item of chapter.mcq) {
      if (item.options.some((option) => fixedLast.test(option))) continue;
      let hash = 0;
      for (const char of item.q) hash = (hash * 31 + char.codePointAt(0)) >>> 0;
      const shift = hash % 4;
      item.options = item.options.map((_, i) => item.options[(i + shift) % 4]);
      item.answer = (item.answer - shift + 4) % 4;
    }
  }
  const replaced = new Set(SSC_CHAPTERS.map((chapter) => chapter.id));
  for (let i = STUDY_CHAPTERS.length - 1; i >= 0; i--) {
    if (replaced.has(STUDY_CHAPTERS[i].id) || removedOld.includes(STUDY_CHAPTERS[i])) STUDY_CHAPTERS.splice(i, 1);
  }
  STUDY_CHAPTERS.push(...SSC_CHAPTERS);
  // প্রশ্নব্যাংকের "গতিসূত্র" অংশ পাঠ্যবইয়ের নাম "বল"-এ সরানো
  const bank = QUESTION_BANK["c9|physics"]?.chapters;
  if (bank?.["গতিসূত্র"]) {
    bank["বল"] = { mcq: [...(bank["বল"]?.mcq ?? []), ...bank["গতিসূত্র"].mcq], short: [...(bank["বল"]?.short ?? []), ...bank["গতিসূত্র"].short] };
    delete bank["গতিসূত্র"];
  }
  // প্রশ্নব্যাংকের অধ্যায়গুলো পাঠ্যবইয়ের ক্রমে সাজানো
  for (const subjectId of new Set(SSC_CHAPTERS.map((chapter) => chapter.subjectId))) {
    const key = "c9|" + subjectId;
    if (!QUESTION_BANK[key]) continue;
    const old = QUESTION_BANK[key].chapters;
    const ordered = {};
    for (const chapter of SSC_CHAPTERS.filter((c) => c.subjectId === subjectId).sort((a, b) => a.number - b.number)) {
      ordered[chapter.chapter] = old[chapter.chapter] ?? { mcq: [], short: [] };
    }
    for (const [name, value] of Object.entries(old)) if (!ordered[name]) ordered[name] = value;
    QUESTION_BANK[key].chapters = ordered;
  }
})();
